def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    if n == 1:
        return 'D' if history[0][1] == 'D' else 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_c = sum(1 for x in op if x == 'C')
    opp_d = n - opp_c
    d5 = sum(1 for x in op[-5:] if x == 'D')
    d10 = sum(1 for x in op[-10:] if x == 'D')

    resp = 0
    resp_coop = 0
    for i in range(1, n):
        if me[i - 1] == 'D':
            resp += 1
            if op[i] == 'C':
                resp_coop += 1

    if resp:
        punish_rate = float(resp - resp_coop) / float(resp)
    else:
        punish_rate = None

    uncooperative = False
    if n >= 5:
        if opp_d > (7 * n) // 10 or d10 >= 7:
            uncooperative = True
        if d5 >= 4 and opp_d > n // 2:
            uncooperative = True
    elif opp_d == n:
        uncooperative = True

    if uncooperative:
        return 'D'

    coop_rate = float(opp_c) / float(n)

    forgiving = False
    tentative_forgiving = False
    non_punitive = False
    punitive = False

    if punish_rate is not None:
        if resp >= 2 and punish_rate <= 0.34 and coop_rate >= 0.6:
            forgiving = True
        if resp >= 1 and punish_rate <= 0.25 and opp_d <= max(1, n // 10):
            tentative_forgiving = True
        if resp >= 5 and 0.45 <= punish_rate <= 0.85 and coop_rate < 0.75:
            non_punitive = True
        if resp >= 4 and punish_rate >= 0.75 and coop_rate < 0.55:
            punitive = True

    if n >= 80:
        if forgiving or tentative_forgiving:
            if n >= 90 and rng.random() < 0.85:
                return 'D'
            if n < 90 and rng.random() < 0.18:
                return 'D'
        elif non_punitive:
            if rng.random() < 0.18:
                return 'D'

    if n >= 95:
        if forgiving or tentative_forgiving:
            return 'D'

    last_me = me[-1]
    last_op = op[-1]

    if last_op == 'D':
        if d5 >= 3:
            return 'D'

        if last_me == 'D':
            if not non_punitive and not punitive and opp_c >= n // 2:
                return 'C'
            return 'D'

        if n >= 2 and me[-2] == 'D':
            if not non_punitive and not punitive and opp_c >= n // 3:
                return 'C'

        return 'D'

    if last_me == 'D':
        if forgiving or tentative_forgiving:
            if n >= 85:
                return 'D'
            if rng.random() < 0.35:
                return 'D'
            return 'C'

        if non_punitive and n >= 60 and rng.random() < 0.18:
            return 'D'

        return 'C'

    if opp_d == 0 and resp == 0 and n >= 80 and n % 5 == 0:
        return 'D'

    if forgiving and n >= 60:
        if rng.random() < 0.08:
            return 'D'

    if tentative_forgiving and n >= 85:
        if rng.random() < 0.20:
            return 'D'

    if non_punitive and n >= 70 and d5 >= 2:
        if rng.random() < 0.22:
            return 'D'

    return 'C'
